import sys

sys.setrecursionlimit(10**6)


def has_cycle(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    color = [0] * n                      # 0 미방문, 1 탐색 중, 2 끝남

    def dfs(u):
        color[u] = 1
        for v in adj[u]:
            if color[v] == 1:            # 탐색 중인 정점으로 돌아옴 → 사이클
                return True
            if color[v] == 0 and dfs(v):
                return True
        color[u] = 2
        return False

    return any(color[u] == 0 and dfs(u) for u in range(n))


print(has_cycle(4, [(0, 1), (1, 2), (2, 3)]))
print(has_cycle(4, [(0, 1), (1, 2), (2, 0), (2, 3)]))
print(has_cycle(3, [(0, 1), (0, 2), (1, 2)]))   # 길이 합쳐질 뿐 사이클은 아니에요

