using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<bool> visited(n + 1, false);    // 정점 1~n
    vector<int> sizes;
    for (int s = 1; s <= n; s++) {
        if (visited[s]) continue;
        visited[s] = true;
        stack<int> st;
        st.push(s);
        int cnt = 0;
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            cnt++;
            for (int v : adj[u])
                if (!visited[v]) {
                    visited[v] = true;
                    st.push(v);
                }
        }
        sizes.push_back(cnt);
    }
    cout << sizes.size() << '\n';
    for (size_t i = 0; i < sizes.size(); i++) cout << sizes[i] << (i + 1 == sizes.size() ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 8;
vector<int> adj[MAXN];                    // 큰 배열은 전역에(지역 배열은 스택에 잡혀요)
int sz[MAXN], dep[MAXN];

void dfs(int u, int parent) {
    sz[u] = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dep[v] = dep[u] + 1;
        dfs(v, u);
        sz[u] += sz[v];                   // 자식이 끝난 뒤(후위) 합치기
    }
}

int main() {
    int n = 7;
    vector<pair<int, int>> edges = {{1, 2}, {1, 3}, {2, 4}, {2, 5}, {3, 6}, {6, 7}};
    for (auto [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    dfs(1, 0);
    for (int u = 1; u <= n; u++) cout << u << ' ' << sz[u] << ' ' << dep[u] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

bool has_cycle(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> adj(n);
    for (auto [u, v] : edges) adj[u].push_back(v);
    vector<int> color(n, 0);              // 0 미방문, 1 탐색 중, 2 끝남
    auto dfs = [&](auto&& self, int u) -> bool {
        color[u] = 1;
        for (int v : adj[u]) {
            if (color[v] == 1) return true;            // 탐색 중인 정점 → 사이클
            if (color[v] == 0 && self(self, v)) return true;
        }
        color[u] = 2;
        return false;
    };
    for (int u = 0; u < n; u++)
        if (color[u] == 0 && dfs(dfs, u)) return true;
    return false;
}

int main() {
    cout << boolalpha;
    cout << has_cycle(4, {{0, 1}, {1, 2}, {2, 3}}) << '\n';
    cout << has_cycle(4, {{0, 1}, {1, 2}, {2, 0}, {2, 3}}) << '\n';
    cout << has_cycle(3, {{0, 1}, {0, 2}, {1, 2}}) << '\n';   // 합쳐질 뿐 사이클 아님
    return 0;
}

